// Test-only worked-case construction. Calls the accepted CLI; never a product runner.
import fs from 'node:fs';
import path from 'node:path';
import crypto from 'node:crypto';
import assert from 'node:assert/strict';
import {spawnSync} from 'node:child_process';
export const cli=path.resolve('scripts/chronicle-kit.mjs');
export const hash=b=>crypto.createHash('sha256').update(b).digest('hex');
export const json=v=>`${JSON.stringify(v,null,2)}\n`;
export function save(root,p,v){fs.mkdirSync(path.dirname(path.join(root,p)),{recursive:true});fs.writeFileSync(path.join(root,p),typeof v==='string'||Buffer.isBuffer(v)?v:json(v));}
export const read=(root,p)=>JSON.parse(fs.readFileSync(path.join(root,p)));
export const ref=(root,p)=>({path:p,sha256:hash(fs.readFileSync(path.join(root,p)))});
export function run(cmd,args){const r=spawnSync(cmd,args,{encoding:'utf8',maxBuffer:64*1024*1024});assert.equal(r.error,undefined,String(r.error));assert.equal(r.status,0,`${cmd} ${args.join(' ')}\n${r.stderr}`);return r.stdout;}
export const kit=(...args)=>JSON.parse(run(process.execPath,[cli,...args]));
export const now=()=>run(process.execPath,[cli,'now']).trim();
export function inventory(root){const o={};function walk(p=''){for(const n of fs.readdirSync(path.join(root,p)).sort()){const q=p?`${p}/${n}`:n,s=fs.lstatSync(path.join(root,q));o[q]=s.isDirectory()?'directory':hash(fs.readFileSync(path.join(root,q)));if(s.isDirectory())walk(q);}}walk();return o;}
export async function later(t){const start=Date.now();while(now()<=t){assert.ok(Date.now()-start<10000,'Clock did not advance: stop instead of fabricating chronology');await new Promise(r=>setTimeout(r,50));}}
export function init(root){fs.mkdirSync(root,{recursive:true});const dataset=path.join(root,'history-data'),workflow=path.join(root,'review-store'),config=path.join(root,'kit.json');run('chronicle',['init',dataset]);save(root,'kit.json',{format_version:1,dataset_path:'history-data',dataset_tracking:'local',workflow_path:'review-store',workflow_tracking:'local'});save(dataset,'project.yaml',{schema_version:1,project:{id:'token-teaching',title:'Synthetic token-import teaching project',description:'Executable toy observations, not real product acceptance.'},display:{timezone:'UTC'}});return {root,dataset,workflow,config,step:0,evidence:[],published:[]};}
export function validate(f,label='final'){const result=JSON.parse(run('chronicle',['validate',f.dataset]));assert.equal(result.valid,true);save(f.root,`${label}-core.json`,result);return result;}
export function observe(f,label,expression,result,expected){assert.deepEqual(result,expected);const report={scope:'Synthetic toy check only; no real product acceptance',expression,result,expected,passed:true,observed_at:now(),occurrence_source:'Machine clock sampled immediately after this check passed; newly observed bounded acceptance, not an inferred historical instant.'};save(f.root,`sources/${label}.json`,report);return report;}
export function captureReport(f,label,id){const record=kit('capture','artifact','--config',f.config,'--source',path.join(f.root,'sources',`${label}.json`),'--id',id,'--artifact',`checks/${label}.json`,'--title',`Toy observation: ${label}`,'--kind','test_output','--media-type','text/plain');const source=fs.readFileSync(path.join(f.root,'sources',`${label}.json`)),captured=fs.readFileSync(path.join(f.dataset,record.source.path));assert.deepEqual(captured,source);assert.equal(hash(captured),record.source.sha256);f.evidence.push(id);return record;}
export function milestone(id,report,{title='Bounded batch capability accepted',summary='The teaching importer accepts the explicitly tested batch.',branch='BR-MAIN',parents=['MAIN-001'],status='accepted',evidence=[],relations}={}){return {schema_version:1,id,occurred_at:report.observed_at,recorded_at:now(),title,summary,branch_id:branch,parents,status,evidence,details:{context:'Synthetic teaching project with explicitly bounded owner criteria.',acceptance_criteria:[report.expression+' equals '+JSON.stringify(report.expected)],results:[JSON.stringify(report.result)],known_limitations:['Only this executable toy input was tested; no production acceptance is claimed.']},...(relations?{relations}:{})};}
export function current(id,state='Single-item parsing accepted'){return {schema_version:1,milestone_id:id,updated_at:now(),state,active_work:['Assess next bounded input'],next_step:'Obtain the next scoped sample',history_projection:[]};}
export function event(id,report,evidence=[]){return {schema_version:1,id,occurred_at:report.observed_at,recorded_at:now(),kind:'test',actor:{type:'tool',label:'toy-check'},outcome:'passed',summary:report.expression+' produced '+JSON.stringify(report.result),...(evidence.length?{evidence}:{})};}
export function baseline(f,{typo=false,code=false}={}){const r=observe(f,'baseline',code?'"1,2".split(",").map(Number)':'Number("1")',code?'1,2'.split(',').map(Number):Number('1'),code?[1,2]:1);captureReport(f,'baseline','EVD-0001');save(f.dataset,'branches/BR-MAIN.yaml',{schema_version:1,id:'BR-MAIN',title:'Quantity import'});save(f.dataset,'milestones/MAIN-001.yaml',milestone('MAIN-001',r,{title:typo?'Singel-item parsing accepted':code?'Nonempty batch parsing accepted':'Single-item parsing accepted',summary:code?'The toy parses the nonempty batch 1,2.':'The toy converts the explicit single quantity 1.',parents:[],evidence:['EVD-0001']}));save(f.dataset,'current.yaml',current('MAIN-001'));validate(f,'baseline');save(f.root,'baseline-inventory.json',inventory(f.dataset));return r;}
export function action(p,v,mode='create'){return {path:p,value:v,action:mode};}
export function bundle(f,packet,expected,actions,{prior=[],mode='new',contributors=[]}={}){const id=`DSP-${crypto.randomUUID()}`,base=`dispositions/${id}`;const evidence=[];const roles=[];for(const evd of f.evidence){const record=read(f.dataset,`evidence/records/${evd}.yaml`);evidence.push({locator:evd,sha256:ref(f.dataset,`evidence/records/${evd}.yaml`).sha256},{locator:record.source.path,sha256:record.source.sha256});roles.push({locator:evd,role:'record'},{locator:record.source.path,role:'artifact'});}
const summary=`# ${packet.title}\n\nStable packet: ${packet.packet_id}\nProducer: ${packet.producer}\nScope: ${packet.project}\n\n${packet.context}\n\nEvidence and limitations: ${packet.evidence.join(' ')}\n\nRuntime evidence bindings:\n${json(evidence)}\n\nAcceptance authority: example-owner; synthetic toy criteria only. Newly supplied information and prior contributors are in the adjacent context.json.\n`;
save(f.workflow,`${base}/work-summary.md`,summary);save(f.workflow,`${base}/recommendation.md`,`# Curator recommendation\n\nPrimary classification: ${expected.classification}\n\nRationale: ${expected.rationale}\n\nEvidence/support limits: ${packet.evidence.join(' ')}\n\nCompanion effects: ${(expected.allowed_companions||[]).join(', ')||'none'}\nUnresolved questions: ${expected.unresolved_questions||'None within the explicitly bounded teaching scope; no production acceptance is claimed.'}\nCandidate relationships: ${JSON.stringify(actions.filter(a=>a.path.startsWith('milestones/')).map(a=>({id:a.value.id,branch:a.value.branch_id,parents:a.value.parents,relations:a.value.relations||[]})))}. Empty means no milestone is proposed. Proposed correction/attachment targets: ${JSON.stringify(actions.filter(a=>a.path.startsWith('revisions/')).map(a=>({target:a.value.target,reason:a.value.reason,changes:a.value.changes})))}.\nThe curator recommends only and does not authorize this proposal.\n`);
const snap=p=>{save(f.workflow,`${base}/context/${p}`,fs.readFileSync(path.join(f.dataset,p)));return ref(f.workflow,`${base}/context/${p}`);};
const cur=fs.existsSync(path.join(f.dataset,'current.yaml'))?read(f.dataset,'current.yaml'):null;
const context={format_version:1,project_id:'token-teaching',current:cur?snap('current.yaml'):null,previous_milestone:cur?{locator:cur.milestone_id,sha256:ref(f.dataset,`milestones/${cur.milestone_id}.yaml`).sha256}:null,roadmap:snap('roadmap.yaml'),history:[],acceptance:{actors:['example-owner'],scope:packet.context},prior_dispositions:prior.map(p=>({id:p.id,sha256:ref(f.workflow,`${p.base}/disposition.json`).sha256})),prior_receipts:prior.filter(p=>p.receipt).map(p=>ref(f.workflow,read(f.workflow,`${p.base}/attempt.json`).receipt)),snapshots:[],evidence_roles:roles,packet_review:{mode,reason:mode==='aggregate'?'New integrated acceptance claim built from explicitly listed earlier subordinate decisions.':expected.rationale,contributors}};
for(const dir of ['milestones','engineering-events','revisions','branches'])if(fs.existsSync(path.join(f.dataset,dir)))for(const name of fs.readdirSync(path.join(f.dataset,dir)).sort())context.history.push(snap(`${dir}/${name}`));
save(f.workflow,`${base}/context.json`,context);const request={format_version:1,inputs:[{packet_id:packet.packet_id,summary:ref(f.workflow,`${base}/work-summary.md`),evidence}],actions:actions.map((a,i)=>{const source=`${base}/inputs/${i}.yaml`;save(f.workflow,source,a.value);return {path:a.path,action:a.action,source};}),warning_reviews:[]};if(actions.length)save(f.workflow,`${base}/request.json`,request);if(actions.length)save(f.workflow,`${base}/author-intent.md`,`${expected.rationale}\nIntent only; not approval. Exact author disposition follows successful preparation.\n`);return {id,base,request,expected};}
export function disposition(f,b,decision=b.expected.decision){const d={format_version:1,id:b.id,recorded_at:now(),actor:'example-owner',inputs:b.request.inputs,context_digest:ref(f.workflow,`${b.base}/context.json`).sha256,recommendation_digest:ref(f.workflow,`${b.base}/recommendation.md`).sha256,classification:b.expected.classification,decision,reason:b.expected.rationale,...(decision==='author'?{proposal_digest:ref(f.workflow,`${b.base}/proposal.json`).sha256}:{})};fs.writeFileSync(path.join(f.workflow,b.base,'disposition.json'),json(d),{flag:'wx'});return d;}
export function prepare(f,b){const before=inventory(f.dataset);const result=kit('prepare','--config',f.config,'--bundle',b.id,'--request',`${b.base}/request.json`);assert.deepEqual(inventory(f.dataset),before);assert.equal(result.state,'PREPARED_UNAPPROVED');assert.equal(read(f.workflow,`${b.base}/proposal.json`).validation.status,'VALID');return result;}
export function apply(f,b){const receipt=kit('apply','--config',f.config,'--bundle',b.id);assert.equal(receipt.state,'PUBLISHED');assert.equal(receipt.validation.status,'VALID');assert.deepEqual(receipt.validation.payload.warnings,[]);assert.equal(receipt.proposal_digest,ref(f.workflow,`${b.base}/proposal.json`).sha256);const replay=Boolean(b.receipt);b.receipt=receipt;if(!replay)save(f.root,`steps/${++f.step}.json`,{packet:b.request.inputs[0].packet_id,bundle:b.base,receipt:read(f.workflow,`${b.base}/attempt.json`).receipt});if(!replay)f.published.push(b);return receipt;}
export function publish(f,packet,expected,actions,options){const b=bundle(f,packet,expected,actions,options);prepare(f,b);disposition(f,b,'author');apply(f,b);return b;}
